insert into academy_paths (code, title, blurb, sort) values ('cs', 'Customer service', 'Requests, offers, renters'' questions, documents and signing, insurer-billed rentals.', 1);
insert into academy_paths (code, title, blurb, sort) values ('sales_in_person', 'Sales in person', 'Selling at the desk: the policies, quotes and offers, cash and the card reader, owner recruitment, commission.', 2);
insert into academy_paths (code, title, blurb, sort) values ('sales_remote', 'Sales remote', 'Selling by chat, text and phone: the policies, quotes and offers, the remote duties, owner recruitment, commission.', 3);
insert into academy_paths (code, title, blurb, sort) values ('field', 'Field work', 'Handovers and returns done right: the checks, photos, readings, cash and signing in the field.', 4);
insert into academy_paths (code, title, blurb, sort) values ('finance', 'Finance', 'Deposits, refunds, payments, tolls, owner debits and payouts, insurer invoices.', 5);
insert into academy_paths (code, title, blurb, sort) values ('fleet', 'Fleet', 'Cars ready, checks, photo reviews, listings, field jobs, hours and trackers.', 6);
insert into academy_paths (code, title, blurb, sort) values ('admin', 'Admin', 'Every policy, the team and the academy, and the money decisions only an Admin makes.', 7);
insert into academy_sections (slug, title, blurb) values ('prices-and-deposits', 'Prices, offers and deposits', 'How a price is built, what an offer does, and the deposit from the hold to the release. With the renter''s questions about price and deposit.');
insert into academy_lessons (section_id, sort, title, scenes) values ((select id from academy_sections where slug = 'prices-and-deposits'), 1, 'How a price is built', '[{"caption":"Every booking starts as a request","say":"A renter never books instantly. They send a request, we check the car and the renter, and we answer with an offer.","visual":{"kind":"title","heading":"Request, offer, pay","text":"Never instant: we always check first"}},{"caption":"The rental charge","say":"The rental charge comes from the car''s rate sheet: a daily rate, a weekend rate, and weekly and monthly rates for longer rentals. The site picks the rate that applies to the days booked.","visual":{"kind":"list","heading":"The rate sheet","items":["Daily rate","Weekend rate","Weekly rate from 7 days","Monthly rate for long rentals"]}},{"caption":"Then the fees and the tax","say":"On top of the rental charge come the fees the booking needs, such as a young driver fee, an additional driver, delivery or add-ons. HST is 13 percent on the lines that carry it.","visual":{"kind":"money","heading":"An example","rows":[["Rental charge, 3 days","$297.00"],["Young driver fee, 3 days at $20","$60.00"],["Delivery","$50.00"],["HST 13%","$52.91"]],"total":["Total","$459.91"]}},{"caption":"Kilometres","say":"Each booking has a kilometre allowance a day. Kilometres over the allowance cost the car''s overage rate, 35 cents a kilometre on most cars, read from the odometer at pickup and return.","visual":{"kind":"rule","heading":"Kilometres","text":"An allowance a day; over it, the car''s rate a km (usually $0.35).","tone":"ok"}},{"caption":"Non-refundable bookings","say":"A renter can choose a non-refundable booking: 10 percent off the rental charge, but no refund if they cancel. Say both halves every time.","visual":{"kind":"rule","heading":"Non-refundable","text":"10% off the rental charge, and no refund on a cancellation.","tone":"warn"}}]'::jsonb);
insert into academy_lessons (section_id, sort, title, scenes) values ((select id from academy_sections where slug = 'prices-and-deposits'), 2, 'What an offer does', '[{"caption":"An offer is our answer","say":"The offer shows the car, the dates, the places and the price. The renter approves it, signs the agreement and pays.","visual":{"kind":"steps","heading":"From offer to booking","items":["Review the offer","Sign the agreement","Pay: the card is authorized","Confirmed: the card is charged"]}},{"caption":"An offer does not hold the car","say":"An offer stays open for 24 hours unless we set another time, at most 48. It does not hold the car: the first renter to pay gets it. If someone else pays first, the renter sees \"This car was just taken\" and their authorization is released.","visual":{"kind":"rule","heading":"First to pay gets the car","text":"Tell a renter who hesitates: the offer does not hold the car.","tone":"warn"}},{"caption":"Changing an offer","say":"An offer that is out is changed in place: Edit the offer, then save and send the update. There is no need to withdraw it first.","visual":{"kind":"title","heading":"Edit the offer","text":"Save and send the update"}},{"caption":"Discount codes","say":"A discount code comes off the rental charge only, never add-ons, fees, the deposit or taxes. A percentage code is capped at 75 dollars, one code per booking, never two codes together.","visual":{"kind":"list","heading":"Discount codes","items":["Rental charge only","Percentage codes capped at $75","One code a booking","Offers only with marketing consent"]}}]'::jsonb);
insert into academy_lessons (section_id, sort, title, scenes) values ((select id from academy_sections where slug = 'prices-and-deposits'), 3, 'The deposit, start to finish', '[{"caption":"A refundable hold","say":"The deposit is refundable. It is a hold on the renter''s card on file, taken about an hour before pickup, not when they pay for the booking.","visual":{"kind":"title","heading":"The deposit","text":"Held about an hour before pickup"}},{"caption":"How much","say":"Each car has a deposit tier: 500, 1,000, 2,500 or 5,000 dollars. Higher-value cars use a higher tier. The offer and the booking always show the amount.","visual":{"kind":"money","heading":"Deposit tiers","rows":[["Tier 1","$500"],["Tier 2","$1,000"],["Tier 3","$2,500"],["Tier 4","$5,000"]]}},{"caption":"Other ways to pay it","say":"Field staff can also take the deposit in cash or by e-Transfer at the handover. Cash is counted in front of the renter and recorded at once.","visual":{"kind":"list","heading":"Deposit methods","items":["Card hold (the usual way)","e-Transfer","Cash, counted and recorded"]}},{"caption":"After the return","say":"After the return we check the car. Tolls, fuel, kilometres over and damage up to the deductible come off the deposit first. The balance comes back within 7 business days.","visual":{"kind":"steps","heading":"Settling the deposit","items":["Return checked","Charges taken off","Balance released within 7 business days"]}},{"caption":"Holding some back","say":"If a toll, a ticket or a claim is still open, we may hold back what we expect it to cost, for up to 30 days. Tell the renter why, and when they can expect the rest.","visual":{"kind":"rule","heading":"Holdback","text":"Up to 30 days for an open toll, ticket or claim.","tone":"warn"}}]'::jsonb);
insert into academy_lessons (section_id, sort, title, scenes) values ((select id from academy_sections where slug = 'prices-and-deposits'), 4, 'Questions about price and deposit', '[{"caption":"\"Why is it so expensive?\"","say":"Do not argue. Explain what the price includes, then offer a real choice.","visual":{"kind":"chat","lines":[{"who":"renter","text":"That is a lot for three days."},{"who":"you","text":"It includes liability coverage and a daily kilometre allowance. A weekly rental brings the daily price down, and a non-refundable booking takes 10% off. Want me to price either?"}]}},{"caption":"\"Why do you need a deposit?\"","say":"The deposit protects the car and the next renter. It is a hold, not a charge, and it comes back.","visual":{"kind":"chat","lines":[{"who":"renter","text":"Why do you hold my money?"},{"who":"you","text":"It is a hold on your card, not a charge. It covers things like tolls or fuel after the trip. The balance is released within 7 business days of the return."}]}},{"caption":"\"Can I skip the deposit?\"","say":"Never promise a waiver. Only an Admin waives a deposit, with a reason that is logged.","visual":{"kind":"chat","lines":[{"who":"renter","text":"Can you skip the deposit for me?"},{"who":"you","text":"I can''t waive it myself. I can ask an Admin, but please plan on the hold. If a card is the problem, field staff can take it in cash or by e-Transfer at pickup."}]}},{"caption":"\"Can I pay with debit?\"","say":"The booking is paid by card. Card coverage needs a credit card in the renter''s name; debit and prepaid cards are refused for that.","visual":{"kind":"chat","lines":[{"who":"renter","text":"Can I use my debit card?"},{"who":"you","text":"To pay, a card in your name works. If you want your card''s rental coverage, it has to be a credit card: debit and prepaid cards do not include it."}]}}]'::jsonb);
insert into academy_questions (section_id, sort, prompt, options, answer, explain) values ((select id from academy_sections where slug = 'prices-and-deposits'), 1, 'When is the deposit taken?', '["When the renter pays for the booking","About an hour before pickup","At the return","Only if there is damage"]'::jsonb, 1, 'The deposit is a hold on the card on file, taken about an hour before pickup.');
insert into academy_questions (section_id, sort, prompt, options, answer, explain) values ((select id from academy_sections where slug = 'prices-and-deposits'), 2, 'A renter has an open offer but has not paid. Another renter pays first for the same car. What happens?', '["The first renter keeps the car for 24 hours","The car goes to the renter who paid","Both bookings are confirmed","Staff must choose"]'::jsonb, 1, 'An offer does not hold the car: the first renter to pay gets it.');
insert into academy_questions (section_id, sort, prompt, options, answer, explain) values ((select id from academy_sections where slug = 'prices-and-deposits'), 3, 'What does a non-refundable booking give and take?', '["5% off, half refunded","10% off the rental charge, no refund on a cancellation","Free delivery, no refund","No deposit, no refund"]'::jsonb, 1, 'Non-refundable is 10% off the rental charge, and no refund if the renter cancels.');
insert into academy_questions (section_id, sort, prompt, options, answer, explain) values ((select id from academy_sections where slug = 'prices-and-deposits'), 4, 'What can a discount code come off?', '["The whole total","The deposit","The rental charge only","Fees and add-ons only"]'::jsonb, 2, 'Codes come off the rental charge only, never add-ons, fees, the deposit or taxes.');
insert into academy_questions (section_id, sort, prompt, options, answer, explain) values ((select id from academy_sections where slug = 'prices-and-deposits'), 5, 'How soon is a deposit balance released after the return?', '["Same day","Within 7 business days","After 30 days","After the next rental"]'::jsonb, 1, 'The balance comes back within 7 business days. An open toll, ticket or claim can hold some back up to 30 days.');
insert into academy_questions (section_id, sort, prompt, options, answer, explain) values ((select id from academy_sections where slug = 'prices-and-deposits'), 6, 'A renter asks you to skip the deposit. What do you say?', '["Yes, for a good customer","Only an Admin can waive it, with a reason; plan on the hold","Deposits are optional","Pay double rent instead"]'::jsonb, 1, 'Only an Admin waives a deposit, with a logged reason. Field staff can take cash or e-Transfer if a card is the problem.');
insert into academy_sections (slug, title, blurb) values ('coverage-and-drivers', 'Coverage, ages and licences', 'The three ways a car is covered (OPCF 27, a credit card''s rental coverage, the CarmaCars Protection Plan), young drivers and licences.');
insert into academy_lessons (section_id, sort, title, scenes) values ((select id from academy_sections where slug = 'coverage-and-drivers'), 1, 'Three ways to cover the car', '[{"caption":"Liability is included","say":"Every rental includes liability coverage. The renter''s choice is about damage to the car itself.","visual":{"kind":"title","heading":"Damage to the car","text":"Liability is included; the renter chooses how damage is covered"}},{"caption":"Option 1: OPCF 27","say":"OPCF 27 is an endorsement on the renter''s own Ontario auto policy that covers a car they rent. The proof: the insurer, the policy number, an expiry after the return date, and the page that shows OPCF 27.","visual":{"kind":"list","heading":"OPCF 27 proof","items":["The insurer","The policy number","Expiry after the return date","The page showing OPCF 27"]}},{"caption":"Option 2: the credit card","say":"The renter pays with a credit card in their own name that includes rental car coverage. Debit and prepaid cards are refused. Most cards stop at a car priced 65,000 or 85,000 dollars, and some of our cars cost more.","visual":{"kind":"rule","heading":"Card coverage","text":"A credit card in the renter''s name; the issuer decides a claim, never us.","tone":"warn"}},{"caption":"Option 3: the Protection Plan","say":"The CarmaCars Protection Plan is priced in the offer, for the car and the driver''s age. Customer service sets its price. A claim still costs the renter the deductible.","visual":{"kind":"title","heading":"The Protection Plan","text":"Priced in the offer"}},{"caption":"Changing the choice","say":"The renter can change their coverage any time before pickup. The agreement changes with it, and they sign the new version.","visual":{"kind":"steps","heading":"Change of coverage","items":["The renter asks","We update the booking","They sign the new version"]}}]'::jsonb);
insert into academy_lessons (section_id, sort, title, scenes) values ((select id from academy_sections where slug = 'coverage-and-drivers'), 2, 'Young drivers, licences and extra drivers', '[{"caption":"Ages","say":"Renters can be 18 or older on some cars. Drivers aged 18 to 20 pay 35 dollars a day; 21 to 25 pay 20 dollars a day. From 26 there is no young driver fee. Some cars set their own fee.","visual":{"kind":"money","heading":"Young driver fees","rows":[["18 to 20","$35 a day"],["21 to 25","$20 a day"],["26 and over","None"]]}},{"caption":"Which cars","say":"Drivers aged 18 to 20 are allowed only on the cars that allow them. If the car asked for does not, offer one that does.","visual":{"kind":"rule","heading":"18 to 20","text":"Only on cars that allow it. Offer a car that does.","tone":"ok"}},{"caption":"Licences","say":"We accept an Ontario G2 or G. A licence from elsewhere is reviewed by a person before we confirm. It must be valid past the return date.","visual":{"kind":"list","heading":"Licence","items":["Class G2 or G","Others: reviewed by a person","Valid past the return"]}},{"caption":"Additional drivers","say":"Each additional driver adds 25 percent of the daily rate, up to 4 drivers. Each one signs the agreement with their own link, or on our device.","visual":{"kind":"rule","heading":"Additional drivers","text":"25% of the daily rate each, up to 4; each signs.","tone":"ok"}}]'::jsonb);
insert into academy_lessons (section_id, sort, title, scenes) values ((select id from academy_sections where slug = 'coverage-and-drivers'), 3, 'Questions about coverage', '[{"caption":"\"My card covers it, right?\"","say":"Never tell a renter they are covered. The card''s issuer decides. Send the card list and ask them to call the number on the back of their card.","visual":{"kind":"chat","lines":[{"who":"renter","text":"My Visa covers rentals, so I''m fine?"},{"who":"you","text":"Many cards do, but only your bank can confirm it for this car and these dates. Here is our list of cards with their limits. Please call the number on the back of your card before pickup."}]}},{"caption":"The car is over the card''s limit","say":"If the car costs more than the card covers, or the card excludes the make, offer OPCF 27 or the Protection Plan instead.","visual":{"kind":"chat","lines":[{"who":"renter","text":"My card stops at $65,000."},{"who":"you","text":"This car is above that, so your card would not cover it. You can add OPCF 27 to your own policy, or take our Protection Plan. Want the Plan''s price?"}]}},{"caption":"\"I don''t have OPCF 27\"","say":"Many renters have never heard of it. It is quick to add with most insurers.","visual":{"kind":"chat","lines":[{"who":"renter","text":"What is OPCF 27? I don''t have it."},{"who":"you","text":"It is an endorsement your insurer adds to your policy to cover a rental car. Many add it in one call. If not, our Protection Plan covers it instead."}]}},{"caption":"\"I''m 19\"","say":"Answer with the fee and the cars that allow it.","visual":{"kind":"chat","lines":[{"who":"renter","text":"I''m 19, can I rent?"},{"who":"you","text":"Yes, on the cars that allow drivers aged 18 to 20, with a $35 a day young driver fee. Let me show you which ones are free for your dates."}]}}]'::jsonb);
insert into academy_questions (section_id, sort, prompt, options, answer, explain) values ((select id from academy_sections where slug = 'coverage-and-drivers'), 1, 'What proves OPCF 27?', '["A photo of the licence","The insurer, policy number, an expiry after the return and the page showing OPCF 27","A bank statement","A verbal promise"]'::jsonb, 1, 'The proof is the insurer, the policy number, an expiry after the return date and the page that shows OPCF 27.');
insert into academy_questions (section_id, sort, prompt, options, answer, explain) values ((select id from academy_sections where slug = 'coverage-and-drivers'), 2, 'A renter wants to use card coverage with a debit card. What do you say?', '["That works","Only a credit card in their name includes it; debit and prepaid are refused","Debit works for cars under $65,000","Ask Finance"]'::jsonb, 1, 'Card coverage needs a credit card in the renter''s own name.');
insert into academy_questions (section_id, sort, prompt, options, answer, explain) values ((select id from academy_sections where slug = 'coverage-and-drivers'), 3, 'A renter asks: "Am I covered by my card?"', '["Yes","No","Only the card''s issuer can say: send the card list and ask them to call their bank","Only if it is Visa"]'::jsonb, 2, 'Never tell a renter they are covered. The issuer decides a claim.');
insert into academy_questions (section_id, sort, prompt, options, answer, explain) values ((select id from academy_sections where slug = 'coverage-and-drivers'), 4, 'What is the young driver fee for a 22-year-old?', '["None","$20 a day","$35 a day","$50 a day"]'::jsonb, 1, 'Drivers aged 21 to 25 pay $20 a day; 18 to 20 pay $35 a day.');
insert into academy_questions (section_id, sort, prompt, options, answer, explain) values ((select id from academy_sections where slug = 'coverage-and-drivers'), 5, 'What does each additional driver cost?', '["Nothing","25% of the daily rate","$10 a booking","The same as the renter"]'::jsonb, 1, 'Each additional driver adds 25% of the daily rate, up to 4 drivers.');
insert into academy_questions (section_id, sort, prompt, options, answer, explain) values ((select id from academy_sections where slug = 'coverage-and-drivers'), 6, 'When can a renter change their coverage choice?', '["Never","Any time before pickup, signing the new version","Only at pickup","Only with an Admin"]'::jsonb, 1, 'They can change it any time before pickup; the agreement changes and they sign it.');
insert into academy_sections (slug, title, blurb) values ('trip-rules', 'Cancellations, late returns, damage, tolls', 'The rules of the trip: cancelling and changing, late returns, kilometres, fuel, cleaning, tolls and tickets, damage and the $2,500 deductible.');
insert into academy_lessons (section_id, sort, title, scenes) values ((select id from academy_sections where slug = 'trip-rules'), 1, 'Cancelling and changing', '[{"caption":"The cancellation table","say":"For a standard booking the refund depends on when the renter cancels. Within 24 hours of booking and 48 hours or more before pickup: 95 percent back. 48 hours or more before pickup: 75 percent. 24 to 48 hours: 50 percent. Under 24 hours: nothing.","visual":{"kind":"money","heading":"Standard booking: cancelled","rows":[["Within 24 h of booking, 48 h+ before pickup","95% back"],["48 h or more before pickup","75% back"],["24 to 48 h before pickup","50% back"],["Under 24 h before pickup","No refund"]]}},{"caption":"Non-refundable means none","say":"A non-refundable booking gets no refund. The deposit is taken at pickup, so none is held when someone cancels before it.","visual":{"kind":"rule","heading":"Non-refundable","text":"No refund. No deposit is held before pickup.","tone":"warn"}},{"caption":"Extend instead of cancel","say":"A renter who wants more time asks to extend before the return time, and pays for the extension before the current return. A date change shows the difference and is signed.","visual":{"kind":"steps","heading":"Extending","items":["Ask before the return time","We approve","Pay before the current return"]}}]'::jsonb);
insert into academy_lessons (section_id, sort, title, scenes) values ((select id from academy_sections where slug = 'trip-rules'), 2, 'On the trip: late, kilometres, fuel, tolls', '[{"caption":"Late returns","say":"There is a 30 minute grace period. After it, a late return costs 25 dollars an hour. A renter running late should ask to extend before their return time.","visual":{"kind":"money","heading":"Late return","rows":[["Grace","30 minutes"],["After that","$25 an hour"]]}},{"caption":"Fuel","say":"Return the car with the fuel it had at pickup. Less is charged at the pump price plus 25 percent, and a 25 dollar service fee. A prepaid full tank means no fuel charge. Electric cars: 10 dollars for each 10 percent of battery.","visual":{"kind":"list","heading":"Fuel","items":["Same level as pickup","Less: pump price + 25%, + $25 service fee","Prepaid full tank: no charge","EV: $10 per 10% of battery"]}},{"caption":"Cleaning and smoking","say":"Normal use is fine. Extra cleaning costs 75 dollars, heavy soiling or odour 250, pet hair 150, and smoking 300.","visual":{"kind":"money","heading":"Cleaning","rows":[["Cleaning","$75"],["Heavy soiling or odour","$250"],["Pet cleaning","$150"],["Smoking","$300"]]}},{"caption":"Tolls and tickets","say":"Tolls and tickets are the renter''s, including the 407 ETR. When one reaches us we pay it and charge the amount plus our fee, 15 dollars a toll and 40 dollars a ticket, to the card on file, with a copy of the notice.","visual":{"kind":"money","heading":"Tolls and tickets","rows":[["Toll","Amount + $15"],["Ticket, fine or towing","Amount + $40"]]}}]'::jsonb);
insert into academy_lessons (section_id, sort, title, scenes) values ((select id from academy_sections where slug = 'trip-rules'), 3, 'Damage and the deductible', '[{"caption":"The deductible","say":"Under our fleet policy, the most a renter pays for damage to the car is the deductible: 2,500 dollars, plus a 75 dollar administration fee for a claim.","visual":{"kind":"money","heading":"Damage","rows":[["Deductible","$2,500"],["Claim administration fee","$75"]]}},{"caption":"How damage is billed","say":"Damage under the deductible is billed from the deposit first, then the card on file. Only an Admin bills damage or keeps a deposit, always with the photos.","visual":{"kind":"steps","heading":"Billing damage","items":["Photos at pickup and return compared","Admin decides, with the photos","Deposit first, then the card on file","More than $2,500 goes through a claim"]}},{"caption":"Reporting","say":"An accident or damage is reported within 48 hours. While the renter has the car, Report a problem on their booking calls roadside help or messages us.","visual":{"kind":"rule","heading":"Report within 48 hours","text":"Report a problem on the booking, or call us.","tone":"warn"}},{"caption":"\"The scratch was already there\"","say":"Stay calm. The handover photos settle it, so point to them.","visual":{"kind":"chat","lines":[{"who":"renter","text":"That scratch was there before!"},{"who":"you","text":"Let''s check together. Every handover has 19 timed photos and a damage diagram. If it is in the pickup photos, it is not yours. If not, an Admin reviews it and tells you before anything is charged."}]}}]'::jsonb);
insert into academy_questions (section_id, sort, prompt, options, answer, explain) values ((select id from academy_sections where slug = 'trip-rules'), 1, 'A renter cancels a standard booking 30 hours before pickup, booked a week ago. What is refunded?', '["95%","75%","50%","Nothing"]'::jsonb, 2, '24 to 48 hours before pickup gives 50% back.');
insert into academy_questions (section_id, sort, prompt, options, answer, explain) values ((select id from academy_sections where slug = 'trip-rules'), 2, 'What does a late return cost?', '["Nothing","$25 an hour after a 30 minute grace","A full day from the first minute","$100 flat"]'::jsonb, 1, 'There is a 30 minute grace, then $25 an hour.');
insert into academy_questions (section_id, sort, prompt, options, answer, explain) values ((select id from academy_sections where slug = 'trip-rules'), 3, 'The car comes back with less fuel. What is charged?', '["Nothing","The pump price plus 25%, and a $25 service fee","A flat $50","The deposit is kept"]'::jsonb, 1, 'Fuel short is the pump price plus 25%, plus a $25 service fee, unless a full tank was prepaid.');
insert into academy_questions (section_id, sort, prompt, options, answer, explain) values ((select id from academy_sections where slug = 'trip-rules'), 4, 'A toll notice arrives. What does the renter pay?', '["Nothing","The amount plus $15","The amount plus $40","Only our fee"]'::jsonb, 1, 'A toll is the amount plus a $15 fee; a ticket is the amount plus $40.');
insert into academy_questions (section_id, sort, prompt, options, answer, explain) values ((select id from academy_sections where slug = 'trip-rules'), 5, 'What is the most a renter pays for damage under our fleet policy?', '["$500","$1,000","The $2,500 deductible, plus $75 for a claim","The full repair"]'::jsonb, 2, 'The deductible is $2,500, plus a $75 administration fee for a claim.');
insert into academy_questions (section_id, sort, prompt, options, answer, explain) values ((select id from academy_sections where slug = 'trip-rules'), 6, 'Who decides to bill damage or keep a deposit?', '["Anyone at the return","An Admin, with the photos","The renter","The owner"]'::jsonb, 1, 'Only an Admin bills damage or keeps a deposit, with the photos.');
insert into academy_questions (section_id, sort, prompt, options, answer, explain) values ((select id from academy_sections where slug = 'trip-rules'), 7, 'Within how long must an accident be reported?', '["48 hours","7 days","30 days","At the return"]'::jsonb, 0, 'Accidents and damage are reported within 48 hours.');
insert into academy_sections (slug, title, blurb) values ('cs-requests', 'Answering requests and messages', 'Claiming a request, the five-minute reply, sending, changing or declining an offer, asking the renter, and the messages that follow.');
insert into academy_lessons (section_id, sort, title, scenes) values ((select id from academy_sections where slug = 'cs-requests'), 1, 'Claiming and the first reply', '[{"caption":"Requests come to you first","say":"A request from the website goes to Admins, customer service and fleet first. Sales may take it after 15 minutes.","visual":{"kind":"list","heading":"Who answers","items":["Admins, customer service, fleet: at once","Sales: after 15 minutes"]}},{"caption":"Opening a request holds it","say":"When you open a request to answer it, it is yours for 20 minutes, renewed while you work. Others see \"Being answered by\" your name. It ends when you send, decline or leave.","visual":{"kind":"rule","heading":"The claim","text":"20 minutes, renewed while you work. Answer or leave it.","tone":"ok"}},{"caption":"Reply within 5 minutes","say":"Reply within 5 minutes in opening hours: send the offer, or ask the renter what you need. It is the first reply measure on your scorecard; requests waiting longer show in red.","visual":{"kind":"title","heading":"5 minutes","text":"Send the offer, or ask the renter"}},{"caption":"Check before you offer","say":"On the Review tab check the car is free, the renter, and the places. Adjust the booking if the car, dates, places, price or extras need to change.","visual":{"kind":"steps","heading":"Answer a request","items":["Open it from Requests","Review: car free, renter, places","Adjust the booking if needed","Add a message, Send the offer"]}}]'::jsonb);
insert into academy_lessons (section_id, sort, title, scenes) values ((select id from academy_sections where slug = 'cs-requests'), 2, 'Offers, declines and changes', '[{"caption":"Within your limit","say":"Within your limit you can also approve and send the pay link at once. Above it, an Admin approves.","visual":{"kind":"rule","heading":"Your limit","text":"Above it, an Admin approves.","tone":"ok"}},{"caption":"Declining well","say":"Can''t do it? Decline with the reason and an alternative: other dates, a similar free car.","visual":{"kind":"chat","lines":[{"who":"you","text":"The Corolla is booked those days. The Civic is free for your dates at the same price. Want me to send that offer?"}]}},{"caption":"Prices you type","say":"You can type a total or a rate a day instead of the rate sheet, with a reason. A price far under the rate sheet is flagged for an Admin, never refused. Choose After tax when you type what the renter paid with HST.","visual":{"kind":"list","heading":"Typed prices","items":["Always give the reason","Far under the sheet: flagged for an Admin","After tax: HST included"]}},{"caption":"A late return","say":"A renter running late should ask to extend before the return time. Approve the extension if the car is free, and remind them to pay before the current return.","visual":{"kind":"chat","lines":[{"who":"renter","text":"I''m stuck in traffic, 40 minutes late."},{"who":"you","text":"Thanks for telling us. After a 30 minute grace it is $25 an hour. If you need longer, I can extend the booking now so it is not a late return."}]}}]'::jsonb);
insert into academy_lessons (section_id, sort, title, scenes) values ((select id from academy_sections where slug = 'cs-requests'), 3, 'Renter messages and records', '[{"caption":"One renter, one record","say":"Search before you add: by name, phone, email or booking number. Already on file? Use them, never a second record. Possible duplicates can be merged.","visual":{"kind":"rule","heading":"Never a second record","text":"Search first; merge duplicates.","tone":"warn"}},{"caption":"Private details","say":"To open a renter''s private details, press Open with a reason. The reason is kept in the access log.","visual":{"kind":"title","heading":"Open with a reason","text":"Every opening is logged"}},{"caption":"Marketing consent","say":"Offer discounts and promotions only to renters who ticked marketing consent. Without it, talk only about their request.","visual":{"kind":"rule","heading":"Consent","text":"No offers without the marketing box ticked.","tone":"warn"}},{"caption":"Reviews","say":"Everyone gets the same review request and the same Google link. Never offer anything for a review and never ask only happy renters.","visual":{"kind":"rule","heading":"Reviews","text":"Same message to everyone; nothing offered for a review.","tone":"warn"}}]'::jsonb);
insert into academy_questions (section_id, sort, prompt, options, answer, explain) values ((select id from academy_sections where slug = 'cs-requests'), 1, 'How long does opening a request to answer it hold it for you?', '["5 minutes","20 minutes, renewed while you work","Until the end of the day","Forever"]'::jsonb, 1, 'The claim lasts 20 minutes and is renewed while you work.');
insert into academy_questions (section_id, sort, prompt, options, answer, explain) values ((select id from academy_sections where slug = 'cs-requests'), 2, 'What is the first reply target in opening hours?', '["5 minutes","1 hour","24 hours","No target"]'::jsonb, 0, 'Reply within 5 minutes: send the offer, or ask the renter.');
insert into academy_questions (section_id, sort, prompt, options, answer, explain) values ((select id from academy_sections where slug = 'cs-requests'), 3, 'When may Sales take a new website request?', '["Never","At once","After 15 minutes","After an hour"]'::jsonb, 2, 'Admins, customer service and fleet answer first; Sales may take it after 15 minutes.');
insert into academy_questions (section_id, sort, prompt, options, answer, explain) values ((select id from academy_sections where slug = 'cs-requests'), 4, 'You type a price far below the rate sheet. What happens?', '["It is refused","It is flagged for an Admin, with your reason","It is sent silently","The renter must approve twice"]'::jsonb, 1, 'A typed price needs a reason; one far under the sheet is flagged, never refused.');
insert into academy_questions (section_id, sort, prompt, options, answer, explain) values ((select id from academy_sections where slug = 'cs-requests'), 5, 'A caller is already on file with that phone number. What do you do?', '["Make a new record","Use the existing record","Ask them for a new email","Ask an Admin"]'::jsonb, 1, 'Never a second record: use the one on file, and merge duplicates.');
insert into academy_questions (section_id, sort, prompt, options, answer, explain) values ((select id from academy_sections where slug = 'cs-requests'), 6, 'A renter has not ticked marketing consent. Can you offer them a promotion?', '["Yes","No: talk only about their request","Only by text","Only with a code"]'::jsonb, 1, 'Without marketing consent, offer nothing beyond their request.');
insert into academy_sections (slug, title, blurb) values ('documents-and-signing', 'Documents, coverage proof and signing', 'Checking licences, selfies and coverage proof; e-signing on the spot or by link; paper signatures and new versions of the agreement.');
insert into academy_lessons (section_id, sort, title, scenes) values ((select id from academy_sections where slug = 'documents-and-signing'), 1, 'Checking documents', '[{"caption":"One screen for everything","say":"Review shows every licence image, selfie and proof of coverage of the booking on one screen, with what to check written above them.","visual":{"kind":"list","heading":"What to check","items":["Name and date of birth match","Class G2 or G, valid past the return","The selfie matches the licence","Coverage active to the return date"]}},{"caption":"Reject with a reason","say":"If one is wrong, reject that one with a reason the renter reads, then approve the rest at once with Approve all.","visual":{"kind":"steps","heading":"Review","items":["Reject the wrong one, with the reason","Approve all for the rest"]}},{"caption":"Coverage proof","say":"OPCF 27 needs the page that shows it and an expiry after the return. Card coverage needs a credit card in the renter''s name. The Protection Plan is confirmed by customer service.","visual":{"kind":"rule","heading":"Coverage","text":"Never approve proof that ends before the return date.","tone":"warn"}}]'::jsonb);
insert into academy_lessons (section_id, sort, title, scenes) values ((select id from academy_sections where slug = 'documents-and-signing'), 2, 'E-sign on the spot', '[{"caption":"Sign now on this device","say":"On the booking, press Sign now on this device. Confirm the name and that you saw the original licence, then hand the device to the signer.","visual":{"kind":"steps","heading":"Sign on the spot","items":["Sign now on this device","Confirm the name and the original licence","Hand the device to the signer","Back to the staff view"]}},{"caption":"What the signer does","say":"Every signature has a code sent to the signer''s phone or email, the key terms initialled, three consents and a drawn signature.","visual":{"kind":"list","heading":"Every signature","items":["A code to their phone or email","Initial the key terms","Three consents","A drawn signature"]}},{"caption":"Or by link","say":"Or press Email the signing link or Text the signing link, and they sign on their own phone.","visual":{"kind":"title","heading":"Signing links","text":"Email or text"}},{"caption":"Changes make a new version","say":"A change to the dates, price, car, drivers or coverage after signing makes a new version that waits for the renter''s signature. Until they sign, the earlier version applies.","visual":{"kind":"rule","heading":"New version","text":"The renter signs again; the old version applies until then.","tone":"ok"}}]'::jsonb);
insert into academy_lessons (section_id, sort, title, scenes) values ((select id from academy_sections where slug = 'documents-and-signing'), 3, 'Paper and the Blind Spot agreement', '[{"caption":"Signed on paper","say":"Signed on paper? Record paper signature on the booking, check who signed and when, and upload every signed page.","visual":{"kind":"steps","heading":"Paper signature","items":["Record paper signature","Choose the agreement","Signed by and date","Upload every page"]}},{"caption":"Two agreements","say":"We rent under Blind Spot Car Rental''s insurance, so each booking has a second agreement, Blind Spot''s form, filled from the same booking. The renter signs both.","visual":{"kind":"title","heading":"Two agreements","text":"CarmaCars and Blind Spot, signed together"}},{"caption":"Fields a claim needs","say":"Check-out stops on a field a claim needs, like a licence expiry or a VIN, until it is filled or an Admin overrides. Fill the missing fields on the booking.","visual":{"kind":"rule","heading":"Missing fields","text":"Fill them before the handover.","tone":"warn"}}]'::jsonb);
insert into academy_questions (section_id, sort, prompt, options, answer, explain) values ((select id from academy_sections where slug = 'documents-and-signing'), 1, 'What must you confirm before handing your device to a signer?', '["Their email","Their name and that you saw the original licence","Their bank","Nothing"]'::jsonb, 1, 'Confirm the name and that you saw the original licence.');
insert into academy_questions (section_id, sort, prompt, options, answer, explain) values ((select id from academy_sections where slug = 'documents-and-signing'), 2, 'The dates change after the renter signed. What happens?', '["Nothing","A new version waits for their signature; the earlier applies until then","The booking is cancelled","An Admin signs for them"]'::jsonb, 1, 'A change makes a new version that the renter signs.');
insert into academy_questions (section_id, sort, prompt, options, answer, explain) values ((select id from academy_sections where slug = 'documents-and-signing'), 3, 'A licence is valid until the day before the return. What do you do?', '["Approve it","Reject it with the reason: it must be valid past the return","Ignore the date","Approve and tell the renter"]'::jsonb, 1, 'The licence must be valid past the return date.');
insert into academy_questions (section_id, sort, prompt, options, answer, explain) values ((select id from academy_sections where slug = 'documents-and-signing'), 4, 'Why is there a Blind Spot agreement?', '["It is optional","We rent under Blind Spot Car Rental''s insurance","For tolls","For owners"]'::jsonb, 1, 'CarmaCars rents under Blind Spot''s insurance, so its form is part of every rental.');
insert into academy_questions (section_id, sort, prompt, options, answer, explain) values ((select id from academy_sections where slug = 'documents-and-signing'), 5, 'What does every e-signature include?', '["Only a typed name","A code, initials on key terms, three consents and a drawn signature","A photo","A payment"]'::jsonb, 1, 'Code, initials, consents and a drawn signature.');
insert into academy_sections (slug, title, blurb) values ('insurer-billed-rentals', 'Insurer-billed rentals and adjusters', 'Insurance replacement rentals: Bill to the insurer, the claim and adjuster, the authorized days and rate, VLF, and emails from Blind Spot.');
insert into academy_lessons (section_id, sort, title, scenes) values ((select id from academy_sections where slug = 'insurer-billed-rentals'), 1, 'Bill to the insurer', '[{"caption":"Insurance replacement","say":"When a renter''s own car is in for repair, their insurer often pays for a rental. The booking is billed to the insurer.","visual":{"kind":"title","heading":"Insurance replacement","text":"The insurer pays; the renter owes the rest"}},{"caption":"Bill to","say":"Choose Bill to: the renter, the insurer pays the rental and fees, or the insurer pays the rental only. With rental only, the renter pays the fees, add-ons and deposit.","visual":{"kind":"list","heading":"Bill to","items":["Renter: pays everything","Insurer: rental and fees","Insurer: rental only; renter pays the rest"]}},{"caption":"The claim details","say":"Record the insurer, the claim number, the adjuster''s name, email and phone, the authorized days and the daily rate authorized, and the provisional end.","visual":{"kind":"steps","heading":"Claim details","items":["Insurer","Claim number","Adjuster: name, email, phone","Authorized days and daily rate","Provisional end"]}},{"caption":"The authorized rate","say":"The daily rate fills in from the insurer''s rate sheet for the car. A rate you type that differs needs a reason. No rate on file? Type what the adjuster authorized.","visual":{"kind":"rule","heading":"The rate","text":"From the insurer''s sheet; a different rate needs a reason.","tone":"ok"}}]'::jsonb);
insert into academy_lessons (section_id, sort, title, scenes) values ((select id from academy_sections where slug = 'insurer-billed-rentals'), 2, 'Adjusters and the insurer invoice', '[{"caption":"Emails from Blind Spot","say":"Insurance emails go from Blind Spot Car Rental and replies come back there. Email the adjuster writes to the adjuster on the booking.","visual":{"kind":"title","heading":"Email the adjuster","text":"Always from Blind Spot Car Rental"}},{"caption":"VLF and other insurer charges","say":"The insurer invoice lists each charge as its own line, like the VLF, the vehicle licence fee, at a rate a day.","visual":{"kind":"money","heading":"Insurer invoice","rows":[["Rental, 5 days at the authorized rate","$275.00"],["VLF: 5 days at $5.00","$25.00"]]}},{"caption":"Extending a claim","say":"The adjuster may authorize more days. Update the authorized days and the provisional end, and keep the renter informed.","visual":{"kind":"chat","lines":[{"who":"renter","text":"My car is not ready yet."},{"who":"you","text":"I will ask your adjuster to authorize more days and confirm with you. Until they approve, days past the authorized end are yours to pay."}]}}]'::jsonb);
insert into academy_questions (section_id, sort, prompt, options, answer, explain) values ((select id from academy_sections where slug = 'insurer-billed-rentals'), 1, 'Bill to "insurer pays the rental only". Who pays the fees and deposit?', '["The insurer","The renter","CarmaCars","Nobody"]'::jsonb, 1, 'With rental only, the renter owes the fees, add-ons and deposit.');
insert into academy_questions (section_id, sort, prompt, options, answer, explain) values ((select id from academy_sections where slug = 'insurer-billed-rentals'), 2, 'You type a daily rate that differs from the insurer''s rate sheet. What is needed?', '["Nothing","A reason","The renter''s signature","A new booking"]'::jsonb, 1, 'A rate that differs from the insurer''s sheet needs a reason.');
insert into academy_questions (section_id, sort, prompt, options, answer, explain) values ((select id from academy_sections where slug = 'insurer-billed-rentals'), 3, 'Which sender is used to email an adjuster?', '["Your own email","CarmaCars","Blind Spot Car Rental","The owner"]'::jsonb, 2, 'Email the adjuster always goes from Blind Spot Car Rental.');
insert into academy_questions (section_id, sort, prompt, options, answer, explain) values ((select id from academy_sections where slug = 'insurer-billed-rentals'), 4, 'What is the VLF?', '["A late fee","The vehicle licence fee, a daily charge to the insurer","A fuel fee","A cleaning fee"]'::jsonb, 1, 'VLF is a daily vehicle licence fee on the insurer invoice.');
insert into academy_questions (section_id, sort, prompt, options, answer, explain) values ((select id from academy_sections where slug = 'insurer-billed-rentals'), 5, 'Which details must an insurer-billed booking carry?', '["Only the insurer","Insurer, claim number, adjuster, authorized days and rate","Only the claim number","The renter''s bank"]'::jsonb, 1, 'All of them: they go on every invoice and email.');
insert into academy_sections (slug, title, blurb) values ('sales-requests-and-quotes', 'Sales: requests, quotes and offers', 'Taking requests after the wait, new quotes for callers, offers sent from a call, discount codes and leads from the website.');
insert into academy_lessons (section_id, sort, title, scenes) values ((select id from academy_sections where slug = 'sales-requests-and-quotes'), 1, 'Requests and quotes', '[{"caption":"When you may answer","say":"Sales sees \"Opens to you at\" a time: a website request opens to you 15 minutes after it came in, with a Sales task when nobody is on it.","visual":{"kind":"title","heading":"Opens to you at","text":"15 minutes after the request"}},{"caption":"A new quote for a caller","say":"New quote: choose the car, the pickup and return at least 2 hours from now, how the lead came in, the caller''s legal name, email, mobile and date of birth, their licence class and damage cover.","visual":{"kind":"steps","heading":"New quote","items":["Car, pickup and return","How the lead came in","Legal name, email, mobile, date of birth","Licence class and damage cover","Create the request, then send the offer"]}},{"caption":"Send an offer from a call","say":"Find the customer or add them, choose the car, dates and places, the price, how it is paid, who found the client and how long it stays open, at most 48 hours.","visual":{"kind":"list","heading":"Offer from a call","items":["Customer: find or add","Car, dates, places","Price with reason if typed","Payment and deposit method","Open at most 48 hours"]}},{"caption":"Example cars","say":"An enquiry on an example car: never offer the example car itself, it does not exist. Offer a real free car of the same kind and price.","visual":{"kind":"rule","heading":"Example cars","text":"Never offer the example car. Offer a real one.","tone":"warn"}}]'::jsonb);
insert into academy_lessons (section_id, sort, title, scenes) values ((select id from academy_sections where slug = 'sales-requests-and-quotes'), 2, 'Closing the sale', '[{"caption":"Urgency without pressure","say":"Be honest about urgency: the offer does not hold the car.","visual":{"kind":"chat","lines":[{"who":"renter","text":"I''ll think about it."},{"who":"you","text":"Of course. Just so you know, the offer doesn''t hold the car: if someone pays first, it''s theirs. Want me to keep it open until tonight?"}]}},{"caption":"Discount codes","say":"Admins and Sales send discount codes: 10 percent off the rental charge, at most 75 dollars, one per booking, only with marketing consent.","visual":{"kind":"money","heading":"A discount code","rows":[["Off the rental charge","10%"],["At most","$75"],["Codes a booking","One"]]}},{"caption":"\"Can I buy it?\"","say":"We mostly rent cars. Never say a car is for sale unless an Admin flagged it. We do not lend or lease.","visual":{"kind":"chat","lines":[{"who":"caller","text":"Can I finance this car?"},{"who":"you","text":"We don''t lend or lease, but you can rent it for a week first. If we find one for sale, I''ll tell you its price."}]}}]'::jsonb);
insert into academy_questions (section_id, sort, prompt, options, answer, explain) values ((select id from academy_sections where slug = 'sales-requests-and-quotes'), 1, 'When does a website request open to Sales?', '["At once","15 minutes after it came in","Never","The next day"]'::jsonb, 1, 'Sales may claim or answer it 15 minutes after it came in.');
insert into academy_questions (section_id, sort, prompt, options, answer, explain) values ((select id from academy_sections where slug = 'sales-requests-and-quotes'), 2, 'How long can an offer stay open at most?', '["12 hours","48 hours","7 days","No limit"]'::jsonb, 1, 'An offer stays open at most 48 hours.');
insert into academy_questions (section_id, sort, prompt, options, answer, explain) values ((select id from academy_sections where slug = 'sales-requests-and-quotes'), 3, 'An enquiry is about an example car. What do you offer?', '["The example car","A real free car of the same kind and price","Nothing","A discount"]'::jsonb, 1, 'Example cars do not exist: offer a real one.');
insert into academy_questions (section_id, sort, prompt, options, answer, explain) values ((select id from academy_sections where slug = 'sales-requests-and-quotes'), 4, 'What is the most a percentage discount code takes off?', '["$25","$75","$200","No cap"]'::jsonb, 1, 'A percentage code is capped at $75.');
insert into academy_questions (section_id, sort, prompt, options, answer, explain) values ((select id from academy_sections where slug = 'sales-requests-and-quotes'), 5, 'A caller asks to finance a car. What do you say?', '["Yes","We do not lend or lease; offer a rental","Send them to the owner","Quote a loan"]'::jsonb, 1, 'We do not lend or lease.');
insert into academy_sections (slug, title, blurb) values ('sales-in-person', 'Sales in person: the desk, cash and the card reader', 'Serving walk-ins, e-signing on the spot, taking payment on the card reader, and handling cash.');
insert into academy_lessons (section_id, sort, title, scenes) values ((select id from academy_sections where slug = 'sales-in-person'), 1, 'At the desk', '[{"caption":"Walk-ins","say":"A walk-in is a renter like any other: one record, the licence checked, the agreement signed and the payment taken before the keys.","visual":{"kind":"steps","heading":"Walk-in","items":["Find or add the renter","Quote and offer","Licence and coverage checked","Sign on this device","Payment and deposit","Handover"]}},{"caption":"The card reader","say":"From the booking''s Money tab, Charge on reader takes what is open, and Hold deposit on reader holds the deposit. Cancel stops the reader. A card read on the reader is never saved as the card on file.","visual":{"kind":"list","heading":"Card reader","items":["Charge on reader","Hold deposit on reader","Cancel stops it","Not saved as the card on file"]}}]'::jsonb);
insert into academy_lessons (section_id, sort, title, scenes) values ((select id from academy_sections where slug = 'sales-in-person'), 2, 'Cash', '[{"caption":"Count it in front of them","say":"Count cash in front of the renter and record it at once. Keep it apart from your own money.","visual":{"kind":"steps","heading":"Cash","items":["Count in front of the renter","Record it at once","Keep it apart","Hand it over as Finance directs"]}},{"caption":"Hand it over","say":"Cash goes to CarmaCars within 1 business day, as Finance directs. Finance counts the drawer at the end of the day: balanced, over or short.","visual":{"kind":"rule","heading":"Within 1 business day","text":"Cash never stays with you.","tone":"warn"}},{"caption":"\"Can I pay all in cash?\"","say":"Cash is accepted for the rental and the deposit when recorded properly.","visual":{"kind":"chat","lines":[{"who":"renter","text":"Can I pay the deposit in cash?"},{"who":"you","text":"Yes. I''ll count it with you and give you a receipt. It comes back the same way after the return, once the car is checked."}]}}]'::jsonb);
insert into academy_questions (section_id, sort, prompt, options, answer, explain) values ((select id from academy_sections where slug = 'sales-in-person'), 1, 'Is a card read on the reader saved as the card on file?', '["Yes","No, never","Only for the deposit","Only with consent"]'::jsonb, 1, 'A card read on the reader is never saved as the card on file.');
insert into academy_questions (section_id, sort, prompt, options, answer, explain) values ((select id from academy_sections where slug = 'sales-in-person'), 2, 'When does cash go to CarmaCars?', '["At the end of the month","Within 1 business day, as Finance directs","When you like","Never"]'::jsonb, 1, 'Cash is handed over within 1 business day.');
insert into academy_questions (section_id, sort, prompt, options, answer, explain) values ((select id from academy_sections where slug = 'sales-in-person'), 3, 'Where do you count cash?', '["In the back office","In front of the renter","At home","At the bank"]'::jsonb, 1, 'Count it in front of the renter and record it at once.');
insert into academy_questions (section_id, sort, prompt, options, answer, explain) values ((select id from academy_sections where slug = 'sales-in-person'), 4, 'How is a cash deposit given back?', '["By card","The way it came, after the return is checked","Never","As a credit"]'::jsonb, 1, 'A deposit taken in cash is given back the same way.');
insert into academy_questions (section_id, sort, prompt, options, answer, explain) values ((select id from academy_sections where slug = 'sales-in-person'), 5, 'What comes before the keys for a walk-in?', '["Nothing","Licence checked, agreement signed, payment and deposit taken","Only payment","Only a signature"]'::jsonb, 1, 'Every check of a handover applies to a walk-in too.');
insert into academy_sections (slug, title, blurb) values ('sales-remote', 'Sales remote: the extra duties', 'Remote Sales: the activity minimum, peak hours, the reply target, live chat and game leads, and consent rules.');
insert into academy_lessons (section_id, sort, title, scenes) values ((select id from academy_sections where slug = 'sales-remote'), 1, 'Your month', '[{"caption":"Touches","say":"Remote Sales logs touches: chats, texts, calls and follow-ups. The minimum is 400 a month.","visual":{"kind":"title","heading":"400 touches a month","text":"The activity minimum"}},{"caption":"Below the minimum","say":"Under the minimum, the month''s commission rate drops one tier. Below the lowest tier the floor is 2.5 percent.","visual":{"kind":"rule","heading":"Below 400","text":"The rate drops one tier (floor 2.5%).","tone":"warn"}},{"caption":"Peak hours","say":"Cover 20 peak hours a week, Thursday to Sunday afternoons, from noon to 6 pm.","visual":{"kind":"list","heading":"Peak hours","items":["Thursday to Sunday","Noon to 6 pm","20 hours a week"]}},{"caption":"Reply in 15 minutes","say":"On chats, texts and calls assigned on your shift, reply within 15 minutes.","visual":{"kind":"title","heading":"15 minutes","text":"Reply target on your shift"}}]'::jsonb);
insert into academy_lessons (section_id, sort, title, scenes) values ((select id from academy_sections where slug = 'sales-remote'), 2, 'Live chat and leads', '[{"caption":"Live chat","say":"Chats waiting for a person show in Live chat. Greet by name when you know it, answer the question asked, then move to a quote.","visual":{"kind":"chat","lines":[{"who":"visitor","text":"Is the RAV4 free next weekend?"},{"who":"you","text":"Let me check. Yes, Friday to Sunday it''s free. Want me to send you an offer now? It takes a minute."}]}},{"caption":"Game leads","say":"Discount game leads come with their code. Without marketing consent, talk only about their request and the code they asked for.","visual":{"kind":"rule","heading":"Game leads","text":"No other offers without consent.","tone":"warn"}},{"caption":"Owner leads too","say":"Remote Sales also works owner leads: Take it, then Update as you go, contacted, qualified, converted or closed with the reason.","visual":{"kind":"steps","heading":"A lead","items":["Take it","Contacted","Qualified","Converted or closed, with the reason"]}}]'::jsonb);
insert into academy_questions (section_id, sort, prompt, options, answer, explain) values ((select id from academy_sections where slug = 'sales-remote'), 1, 'What is the remote Sales activity minimum?', '["100 touches a month","400 touches a month","1,000 a week","None"]'::jsonb, 1, 'The minimum is 400 touches a month.');
insert into academy_questions (section_id, sort, prompt, options, answer, explain) values ((select id from academy_sections where slug = 'sales-remote'), 2, 'What happens below the minimum?', '["Nothing","The month''s rate drops one tier (floor 2.5%)","No commission at all","A warning only"]'::jsonb, 1, 'The rate drops one tier, with a 2.5% floor.');
insert into academy_questions (section_id, sort, prompt, options, answer, explain) values ((select id from academy_sections where slug = 'sales-remote'), 3, 'Which hours are the peak hours?', '["Monday mornings","Thursday to Sunday, noon to 6 pm","Nights","Any time"]'::jsonb, 1, 'Thursday to Sunday afternoons, noon to 6 pm, 20 hours a week.');
insert into academy_questions (section_id, sort, prompt, options, answer, explain) values ((select id from academy_sections where slug = 'sales-remote'), 4, 'What is the reply target on your shift?', '["5 minutes","15 minutes","1 hour","24 hours"]'::jsonb, 1, 'Remote Sales replies within 15 minutes on their shift.');
insert into academy_questions (section_id, sort, prompt, options, answer, explain) values ((select id from academy_sections where slug = 'sales-remote'), 5, 'A game lead has no marketing consent. What may you discuss?', '["Any offer","Only their request and the code they asked for","Nothing","Other cars on sale"]'::jsonb, 1, 'Without consent, only their request and their code.');
insert into academy_sections (slug, title, blurb) values ('owner-recruitment', 'Recruiting car owners', 'The pitch to a car owner, what they pay and earn, and the objections: insurance, wear, trust, leaving.');
insert into academy_lessons (section_id, sort, title, scenes) values ((select id from academy_sections where slug = 'owner-recruitment'), 1, 'The pitch', '[{"caption":"What we offer","say":"An owner lists their car with us. Managed: we do everything, pricing, renters, handovers and cleaning, and pay them each month less the Revenue Share. Self-Managed: they hand over to their own renters, who book and pay through us.","visual":{"kind":"list","heading":"Two ways","items":["Managed: we do everything","Self-Managed: their renters, our booking and payment"]}},{"caption":"What they pay","say":"Each car has a monthly insurance fee and a tracker fee, due every month rented or not. The tracker install has its own invoice. Before going live they pay the first and last month agreed.","visual":{"kind":"money","heading":"Owner fees","rows":[["Insurance fee","Monthly, as agreed"],["Tracker fee","Monthly, from install"],["Tracker install","One invoice"],["First and last month","Before going live"]]}},{"caption":"When they are paid","say":"Payouts for the month before arrive on the 10th with a statement. Fees are debited on the 15th after a notice 10 days before.","visual":{"kind":"steps","heading":"The owner month","items":["10th: payout and statement","5th: notice of the debit","15th: fees debited"]}},{"caption":"A flat monthly amount","say":"Some owners prefer the same amount every month for a car instead of a revenue share and fees. Only an Admin sets it, car by car.","visual":{"kind":"rule","heading":"Flat monthly","text":"Admin only, car by car.","tone":"ok"}}]'::jsonb);
insert into academy_lessons (section_id, sort, title, scenes) values ((select id from academy_sections where slug = 'owner-recruitment'), 2, 'Owner objections', '[{"caption":"\"What about insurance?\"","say":"Rentals run on our fleet policy once the car is added to it. The owner''s own policy details are collected.","visual":{"kind":"chat","lines":[{"who":"owner","text":"My insurance won''t cover rentals."},{"who":"you","text":"Rentals run on our fleet policy once your car is added. That''s what the monthly insurance fee covers. Your own policy stays in place for your use."}]}},{"caption":"\"What about wear and damage?\"","say":"Every handover has 19 timed photos, a damage diagram and a tracker. Damage is billed to the renter up to the deductible, and claims go through the policy.","visual":{"kind":"chat","lines":[{"who":"owner","text":"Renters will wreck my car."},{"who":"you","text":"Every pickup and return has 19 timed photos and a tracker. Damage is billed to the renter up to the $2,500 deductible, and bigger damage goes through a claim."}]}},{"caption":"\"Can I leave?\"","say":"Yes. 30 days'' notice on a car; the exit date is the end of the notice, or the end of a rental in progress if later.","visual":{"kind":"chat","lines":[{"who":"owner","text":"What if I want out?"},{"who":"you","text":"Give 30 days'' notice in your portal. The car leaves at the end of the notice, or after a rental in progress."}]}},{"caption":"\"Can you raise my fees?\"","say":"A higher fee needs 30 days'' written notice; a higher Revenue Share only once the owner signs an updated Vehicle Schedule.","visual":{"kind":"rule","heading":"Changes","text":"Higher fee: 30 days'' notice. Higher share: the owner signs.","tone":"ok"}}]'::jsonb);
insert into academy_questions (section_id, sort, prompt, options, answer, explain) values ((select id from academy_sections where slug = 'owner-recruitment'), 1, 'What is a Managed owner''s deal?', '["They do everything","We do everything and pay them monthly less the Revenue Share","They pay a flat fee only","They sell us the car"]'::jsonb, 1, 'Managed: we handle everything; they are paid less the Revenue Share.');
insert into academy_questions (section_id, sort, prompt, options, answer, explain) values ((select id from academy_sections where slug = 'owner-recruitment'), 2, 'When are the owner''s fees due?', '["Only when the car rents","Every month, rented or not","Once a year","Never"]'::jsonb, 1, 'The insurance and tracker fees are due every month, rented or not.');
insert into academy_questions (section_id, sort, prompt, options, answer, explain) values ((select id from academy_sections where slug = 'owner-recruitment'), 3, 'When do owners get their payout?', '["The 1st","The 10th, with a statement","The 15th","The 30th"]'::jsonb, 1, 'Payouts arrive on the 10th with a statement; fees are debited on the 15th.');
insert into academy_questions (section_id, sort, prompt, options, answer, explain) values ((select id from academy_sections where slug = 'owner-recruitment'), 4, 'An owner wants to leave. What notice applies?', '["None","30 days on that car","6 months","1 year"]'::jsonb, 1, '30 days'' notice; the exit is at the end of the notice or of a rental in progress.');
insert into academy_questions (section_id, sort, prompt, options, answer, explain) values ((select id from academy_sections where slug = 'owner-recruitment'), 5, 'Who sets a flat monthly amount for a car?', '["Any staff","Only an Admin, car by car","The owner alone","Finance"]'::jsonb, 1, 'Only an Admin, car by car.');
insert into academy_questions (section_id, sort, prompt, options, answer, explain) values ((select id from academy_sections where slug = 'owner-recruitment'), 6, 'Can CarmaCars raise an owner''s Revenue Share by notice alone?', '["Yes","No: the owner signs an updated Vehicle Schedule","Yes, with 7 days","Only for new cars"]'::jsonb, 1, 'A higher share applies only once the owner signs.');
insert into academy_sections (slug, title, blurb) values ('commission', 'Commission', 'How commission is worked out: the Sales tiers in person and remote, the rate of the other functions, and what counts.');
insert into academy_lessons (section_id, sort, title, scenes) values ((select id from academy_sections where slug = 'commission'), 1, 'The tiers', '[{"caption":"A share of the rental charge","say":"Commission is a share of the rental charge of the rentals you close, never of fees, add-ons or taxes.","visual":{"kind":"title","heading":"Commission","text":"A share of the rental charge"}},{"caption":"Sales in person","say":"In person: 10 percent, 15 percent once the month reaches 50 rental days, and 20 percent from 100 rental days, the month''s target.","visual":{"kind":"money","heading":"Sales in person","rows":[["Under 50 rental days","10%"],["From 50","15%"],["From 100","20%"]]}},{"caption":"Sales remote","say":"Remote: 5, 10 and 15 percent on the same tiers, with the activity minimum.","visual":{"kind":"money","heading":"Sales remote","rows":[["Under 50 rental days","5%"],["From 50","10%"],["From 100","15%"]]}},{"caption":"Other functions","say":"Customer service, finance, fleet and field staff earn 10 percent on the rentals they close. Admin can change every rate in Program settings.","visual":{"kind":"rule","heading":"Other staff","text":"10% of the rental charge.","tone":"ok"}}]'::jsonb);
insert into academy_questions (section_id, sort, prompt, options, answer, explain) values ((select id from academy_sections where slug = 'commission'), 1, 'Commission is a share of what?', '["The total with tax","The rental charge","Fees and add-ons","The deposit"]'::jsonb, 1, 'Commission is a share of the rental charge only.');
insert into academy_questions (section_id, sort, prompt, options, answer, explain) values ((select id from academy_sections where slug = 'commission'), 2, 'In person Sales reaches 60 rental days this month. What rate applies?', '["10%","15%","20%","5%"]'::jsonb, 1, 'From 50 rental days the rate is 15%; from 100, 20%.');
insert into academy_questions (section_id, sort, prompt, options, answer, explain) values ((select id from academy_sections where slug = 'commission'), 3, 'What is the top remote Sales rate?', '["10%","15%","20%","25%"]'::jsonb, 1, 'Remote tiers are 5%, 10% and 15%.');
insert into academy_questions (section_id, sort, prompt, options, answer, explain) values ((select id from academy_sections where slug = 'commission'), 4, 'What do customer service staff earn on a rental they close?', '["Nothing","10% of the rental charge","20%","A flat $50"]'::jsonb, 1, 'Staff outside Sales earn 10%.');
insert into academy_questions (section_id, sort, prompt, options, answer, explain) values ((select id from academy_sections where slug = 'commission'), 5, 'Who can change the commission rates?', '["Anyone","An Admin, in Program settings","Finance","The renter"]'::jsonb, 1, 'Admin changes them in Program settings.');
insert into academy_sections (slug, title, blurb) values ('field-handover', 'The handover', 'The ready check, the original licence and card, odometer, fuel, keys, 19 photos, damage, tracker and signatures.');
insert into academy_lessons (section_id, sort, title, scenes) values ((select id from academy_sections where slug = 'field-handover'), 1, 'The ready check', '[{"caption":"Every line green","say":"The first step lists what must be done before the car can go: agreement signed, identity verified, coverage confirmed, additional drivers accepted, the calendar held, and the deposit taken.","visual":{"kind":"list","heading":"Ready check","items":["Agreement signed","Identity verified","Coverage confirmed","Additional drivers accepted","Calendar held","Deposit taken"]}},{"caption":"Never hand over on a red line","say":"Never hand over keys if the ready check fails, the renter does not match the photo, or they do not have the original licence or the card on file. Stop and call us.","visual":{"kind":"rule","heading":"Stop","text":"A failed check, a face that does not match, no original licence or card: stop and call.","tone":"warn"}},{"caption":"Fix it on the spot","say":"Most red lines are fixed on your phone: sign now on this device, take the licence photos, hand the phone for the card hold, or record an e-Transfer or cash.","visual":{"kind":"steps","heading":"Fix on the spot","items":["Not signed: sign on this device","Not verified: take licence and selfie","No deposit: card hold on this phone","Or record e-Transfer or cash"]}}]'::jsonb);
insert into academy_lessons (section_id, sort, title, scenes) values ((select id from academy_sections where slug = 'field-handover'), 2, 'The steps, one by one', '[{"caption":"The renter and the documents","say":"Is this the renter? Compare the person with the photo. Hold the original licence: a photo of a licence is not enough. See the physical card with the same last four digits, in the renter''s name.","visual":{"kind":"list","heading":"Check","items":["Person matches the photo","Original licence","Physical card, same last four"]}},{"caption":"Readings","say":"Type the odometer in kilometres. Tap the fuel or charge level, in eighths from empty to full. Count the keys and fobs.","visual":{"kind":"steps","heading":"Readings","items":["Odometer in km","Fuel in eighths","Keys and fobs"]}},{"caption":"Photos and damage","say":"Take the 19 photos in order. Tap the diagram where damage is, choose where and the type, and add it. Photos wait on the phone without a connection and upload by themselves.","visual":{"kind":"title","heading":"19 photos","text":"In order, with every damage marked"}},{"caption":"Tracker and signatures","say":"The tracker should say in place and reporting. The renter reads the summary, signs, then you sign. Press Hand over the keys.","visual":{"kind":"steps","heading":"Finish","items":["Tracker reporting","Renter reviews the summary","Renter signs, then you","Hand over the keys"]}}]'::jsonb);
insert into academy_questions (section_id, sort, prompt, options, answer, explain) values ((select id from academy_sections where slug = 'field-handover'), 1, 'The renter shows a photo of their licence on their phone. Can you proceed?', '["Yes","No: you need the original licence","Yes, if the face matches","Ask the renter to email it"]'::jsonb, 1, 'A photo of a licence is not enough.');
insert into academy_questions (section_id, sort, prompt, options, answer, explain) values ((select id from academy_sections where slug = 'field-handover'), 2, 'How many photos does a handover take?', '["5","10","19","50"]'::jsonb, 2, 'The photo set has 19 photos in order.');
insert into academy_questions (section_id, sort, prompt, options, answer, explain) values ((select id from academy_sections where slug = 'field-handover'), 3, 'How is fuel recorded?', '["In litres","In eighths from empty to full","As a percentage typed","Not recorded"]'::jsonb, 1, 'Tap the level on the gauge, in eighths.');
insert into academy_questions (section_id, sort, prompt, options, answer, explain) values ((select id from academy_sections where slug = 'field-handover'), 4, 'The ready check shows the deposit is not taken. What can you do?', '["Hand over anyway","Card hold on this phone, or record e-Transfer or cash","Cancel the booking","Skip it"]'::jsonb, 1, 'Fix it on the spot: card hold on your phone, or e-Transfer or cash.');
insert into academy_questions (section_id, sort, prompt, options, answer, explain) values ((select id from academy_sections where slug = 'field-handover'), 5, 'The renter''s face does not match the photo on file. What do you do?', '["Proceed","Stop: do not release the car, and call us","Take a new selfie","Ask for a second ID"]'::jsonb, 1, 'Stop and call us.');
insert into academy_sections (slug, title, blurb) values ('field-return-and-cash', 'Returns, cash and signing in the field', 'The return check, late and fuel readings, damage at the return, cash and e-Transfer deposits, and signing on your phone.');
insert into academy_lessons (section_id, sort, title, scenes) values ((select id from academy_sections where slug = 'field-return-and-cash'), 1, 'The return', '[{"caption":"Check with the renter","say":"At the return check the odometer, fuel or charge, keys and cleanliness, take the photos and compare with the pickup. The renter signs on your screen.","visual":{"kind":"steps","heading":"The return","items":["Odometer and fuel","Keys and cleanliness","Photos compared with pickup","The renter signs"]}},{"caption":"The readings make the charges","say":"A late return, kilometres over the allowance and less fuel than at pickup are charged from your readings, so record them exactly.","visual":{"kind":"rule","heading":"Exact readings","text":"Your readings decide the charges.","tone":"warn"}},{"caption":"New damage","say":"Mark new damage on the diagram with close-ups. Do not promise the renter a charge or no charge: an Admin decides, with the photos.","visual":{"kind":"chat","lines":[{"who":"renter","text":"Will I be charged for that?"},{"who":"you","text":"I''ve recorded it with photos. An Admin reviews it against the pickup photos and contacts you before anything is charged."}]}}]'::jsonb);
insert into academy_lessons (section_id, sort, title, scenes) values ((select id from academy_sections where slug = 'field-return-and-cash'), 2, 'Cash and signing on your phone', '[{"caption":"Cash deposits","say":"Paid in cash: count the amount in front of the renter and press I received. Keep it apart from your own money and hand it to CarmaCars within 1 business day, as Finance directs.","visual":{"kind":"steps","heading":"Cash","items":["Count in front of them","I received","Keep it apart","Hand over within 1 business day"]}},{"caption":"e-Transfer","say":"Paid by e-Transfer: type the reference number from their confirmation and record it.","visual":{"kind":"title","heading":"Record the e-Transfer","text":"With the reference number"}},{"caption":"Sign now on this device","say":"Not signed yet? Sign now on this device: check the name matches the licence and you saw the original, hand the phone over, and take it back when they finish.","visual":{"kind":"list","heading":"Sign on your phone","items":["Name matches the licence","You saw the original","Hand the device over","Back to the staff view"]}}]'::jsonb);
insert into academy_questions (section_id, sort, prompt, options, answer, explain) values ((select id from academy_sections where slug = 'field-return-and-cash'), 1, 'What decides the late, kilometre and fuel charges?', '["The renter''s word","Your readings at the return","The office''s guess","Nothing"]'::jsonb, 1, 'The readings you record decide the charges.');
insert into academy_questions (section_id, sort, prompt, options, answer, explain) values ((select id from academy_sections where slug = 'field-return-and-cash'), 2, 'A renter asks if they will be charged for new damage. What do you say?', '["Yes","No","An Admin reviews it with the photos and contacts them first","Pay me now"]'::jsonb, 2, 'Never promise; an Admin decides with the photos.');
insert into academy_questions (section_id, sort, prompt, options, answer, explain) values ((select id from academy_sections where slug = 'field-return-and-cash'), 3, 'You received a cash deposit. When does it go to CarmaCars?', '["At month end","Within 1 business day","Never","When the renter returns"]'::jsonb, 1, 'Within 1 business day, as Finance directs.');
insert into academy_questions (section_id, sort, prompt, options, answer, explain) values ((select id from academy_sections where slug = 'field-return-and-cash'), 4, 'What do you record for an e-Transfer?', '["Nothing","The reference number from their confirmation","Their bank password","A photo of the car"]'::jsonb, 1, 'Type the reference number and record it.');
insert into academy_questions (section_id, sort, prompt, options, answer, explain) values ((select id from academy_sections where slug = 'field-return-and-cash'), 5, 'Before handing your phone to sign, what do you check?', '["Their email","The name matches the licence and you saw the original","Their address","Nothing"]'::jsonb, 1, 'Check the name and the original licence.');
insert into academy_sections (slug, title, blurb) values ('finance-deposits-refunds', 'Finance: deposits, refunds and payments', 'Settling deposits, the toll window, refunds by the policy, payments received another way, and the day''s cash count.');
insert into academy_lessons (section_id, sort, title, scenes) values ((select id from academy_sections where slug = 'finance-deposits-refunds'), 1, 'Settling a deposit', '[{"caption":"The settlement","say":"Settle the deposit applies what is owed, holds back what an open item needs, and releases the rest. What the deposit does not cover is charged to the card on file.","visual":{"kind":"steps","heading":"Settle","items":["Charges owed","Hold back for open items","Release the rest"]}},{"caption":"The toll window","say":"Tolls and tickets can take up to 7 days to come in. Inside that window the rest of the deposit is held back until the window ends, unless you release it sooner.","visual":{"kind":"rule","heading":"Toll window","text":"7 days; the hold-back can be released early.","tone":"ok"}},{"caption":"Something still open","say":"An incident, a claim, unpriced damage or an unmatched toll keeps the whole deposit. Damage: only an Admin keeps the deposit or bills up to the 2,500 dollar deductible.","visual":{"kind":"rule","heading":"Open items","text":"Keep the deposit; damage goes to an Admin.","tone":"warn"}},{"caption":"Card holds lapse","say":"A card hold lapses after about 7 days. While the car is out or not settled, the hold is collected in full a day and a half before it lapses, and the settlement refunds the rest.","visual":{"kind":"title","heading":"Holds","text":"Collected before they lapse; refunded at settlement"}}]'::jsonb);
insert into academy_lessons (section_id, sort, title, scenes) values ((select id from academy_sections where slug = 'finance-deposits-refunds'), 2, 'Refunds and payments', '[{"caption":"Refunds by the policy","say":"Refunds waiting shows the policy maths: what was paid, the tier, the percentage back and what is kept. Approve or decline with the reason. Above your limit, an Admin approves.","visual":{"kind":"list","heading":"A refund","items":["Paid","The tier","Percentage back","What is kept"]}},{"caption":"Paid another way","say":"A renter paid by e-Transfer, cheque or cash? Record the payment with the date, the reference and the proof. A partial payment leaves the rest open.","visual":{"kind":"steps","heading":"Record a payment","items":["Paid by","Date received","Reference","Proof","Record payment"]}},{"caption":"The drawer","say":"At the end of the day count the drawer and record the count. The difference shows balanced, over or short.","visual":{"kind":"title","heading":"Record the count","text":"Balanced, over or short"}}]'::jsonb);
insert into academy_questions (section_id, sort, prompt, options, answer, explain) values ((select id from academy_sections where slug = 'finance-deposits-refunds'), 1, 'How long is the toll window?', '["1 day","7 days","30 days","90 days"]'::jsonb, 1, 'Tolls and tickets can take up to 7 days to come in.');
insert into academy_questions (section_id, sort, prompt, options, answer, explain) values ((select id from academy_sections where slug = 'finance-deposits-refunds'), 2, 'An incident is open on a returned car. What happens to the deposit?', '["Release it","The whole deposit is kept until it is resolved","Half is released","It is charged at once"]'::jsonb, 1, 'Something still open keeps the whole deposit.');
insert into academy_questions (section_id, sort, prompt, options, answer, explain) values ((select id from academy_sections where slug = 'finance-deposits-refunds'), 3, 'Who may keep a deposit for damage?', '["Finance","An Admin","Field staff","The renter"]'::jsonb, 1, 'Only an Admin keeps a deposit or bills damage.');
insert into academy_questions (section_id, sort, prompt, options, answer, explain) values ((select id from academy_sections where slug = 'finance-deposits-refunds'), 4, 'A refund is above your limit. What happens?', '["It is refused","It waits for an Admin","It goes through anyway","It is split"]'::jsonb, 1, 'Above your limit, an Admin approves.');
insert into academy_questions (section_id, sort, prompt, options, answer, explain) values ((select id from academy_sections where slug = 'finance-deposits-refunds'), 5, 'What do you record at the end of the day?', '["Nothing","The drawer count","The weather","The fleet mileage"]'::jsonb, 1, 'Count the drawer and record it: balanced, over or short.');
insert into academy_sections (slug, title, blurb) values ('finance-tolls-owners', 'Finance: tolls, owners and insurers', 'Reading toll notices, who pays, owner invoices and debits, payouts and statements, and insurer invoices.');
insert into academy_lessons (section_id, sort, title, scenes) values ((select id from academy_sections where slug = 'finance-tolls-owners'), 1, 'Tolls and tickets', '[{"caption":"Read a notice","say":"Read a notice: upload the PDF, photo or CSV, check each line against the notice, then confirm and import. Renters matched with high confidence are charged at import, with the notice and our fee.","visual":{"kind":"steps","heading":"A notice","items":["Read it","Check each line","Save as checked","Confirm and import"]}},{"caption":"Who pays","say":"Decide who pays a toll: charge the renter, bill it to the owner, or CarmaCars pays. A renter pays the amount plus 15 dollars a toll or 40 dollars a ticket.","visual":{"kind":"list","heading":"Who pays","items":["Charge the renter","Bill to the owner","CarmaCars pays"]}}]'::jsonb);
insert into academy_lessons (section_id, sort, title, scenes) values ((select id from academy_sections where slug = 'finance-tolls-owners'), 2, 'Owners and insurers', '[{"caption":"The owner month","say":"Owner fees are debited on the 15th after a notice 10 days before. Payouts and statements go out on the 10th.","visual":{"kind":"steps","heading":"The owner month","items":["10th: payouts and statements","5th: debit notice","15th: debits"]}},{"caption":"A returned debit","say":"Returned for insufficient funds: a 50 dollar late fee once, and the same amount tried again within 30 days. Returned for another reason: no retry, the debit pauses and the owner is emailed.","visual":{"kind":"money","heading":"Returned debit","rows":[["Insufficient funds","$50 late fee, retry within 30 days"],["Other reason","No retry, debit paused"]]}},{"caption":"Insurer invoices","say":"Insurer-billed rentals are invoiced to the insurer: each charge a line of its own, like the VLF at a rate a day, with the claim number.","visual":{"kind":"title","heading":"Insurer invoice","text":"Each charge its own line, with the claim number"}}]'::jsonb);
insert into academy_questions (section_id, sort, prompt, options, answer, explain) values ((select id from academy_sections where slug = 'finance-tolls-owners'), 1, 'A renter is matched to a toll with high confidence. When are they charged?', '["Never","At import, with the notice and our fee","At the next booking","After 90 days"]'::jsonb, 1, 'High-confidence matches are charged at import.');
insert into academy_questions (section_id, sort, prompt, options, answer, explain) values ((select id from academy_sections where slug = 'finance-tolls-owners'), 2, 'When are owner fees debited?', '["The 1st","The 10th","The 15th, after a 10-day notice","The 30th"]'::jsonb, 2, 'Debits are on the 15th after a notice 10 days before.');
insert into academy_questions (section_id, sort, prompt, options, answer, explain) values ((select id from academy_sections where slug = 'finance-tolls-owners'), 3, 'An owner''s debit returns for insufficient funds. What happens?', '["Nothing","A $50 late fee once, and a retry within 30 days","The car is removed","A retry the same day"]'::jsonb, 1, 'A $50 late fee once; the same amount is tried again within 30 days.');
insert into academy_questions (section_id, sort, prompt, options, answer, explain) values ((select id from academy_sections where slug = 'finance-tolls-owners'), 4, 'A debit returns because the account is closed. What happens?', '["Retry tomorrow","No retry; the debit pauses and the owner is emailed","Late fee and retry","Charge the card"]'::jsonb, 1, 'Another reason: no retry and no late fee; the debit pauses.');
insert into academy_questions (section_id, sort, prompt, options, answer, explain) values ((select id from academy_sections where slug = 'finance-tolls-owners'), 5, 'What goes on every insurer invoice line?', '["Nothing special","The claim number, with each charge on its own line","The renter''s card","The owner''s bank"]'::jsonb, 1, 'Each charge is its own line, with the claim number.');
insert into academy_sections (slug, title, blurb) values ('fleet-cars', 'Fleet: cars, checks and listings', 'Daily checks, maintenance, photo reviews after a return, listings and plates, and the turnaround between trips.');
insert into academy_lessons (section_id, sort, title, scenes) values ((select id from academy_sections where slug = 'fleet-cars'), 1, 'Keeping cars ready', '[{"caption":"Daily checks","say":"Open the daily checks morning and evening. Tick OK or Problem with a note, and save.","visual":{"kind":"steps","heading":"Daily check","items":["Opening or closing check","OK or Problem with a note","Save"]}},{"caption":"The turnaround","say":"Between trips the car needs a turnaround of 2 hours for cleaning and checks. Do not squeeze a booking into it.","visual":{"kind":"rule","heading":"Turnaround","text":"2 hours between trips.","tone":"ok"}},{"caption":"Car ready means","say":"A car is ready when the fuel is full or the charge at 80 percent, it is clean, and the extras are in.","visual":{"kind":"list","heading":"Ready","items":["Fuel full or charge 80%","Clean","Extras in"]}}]'::jsonb);
insert into academy_lessons (section_id, sort, title, scenes) values ((select id from academy_sections where slug = 'fleet-cars'), 2, 'After a return', '[{"caption":"Photo reviews","say":"After a return, compare the return photos with the pickup photos. New damage goes to an Admin with the photos.","visual":{"kind":"title","heading":"Photo review","text":"Pickup against return"}},{"caption":"Waiving a charge","say":"Fleet can waive a return charge, like fuel or cleaning, with a reason. Damage is an Admin''s decision.","visual":{"kind":"rule","heading":"Waive","text":"With a reason; never damage.","tone":"warn"}},{"caption":"Listings and plates","say":"Listing photos stay private until the plate is covered or marked not visible. Check each photo before it goes public.","visual":{"kind":"title","heading":"Plates","text":"Covered before a photo is public"}}]'::jsonb);
insert into academy_questions (section_id, sort, prompt, options, answer, explain) values ((select id from academy_sections where slug = 'fleet-cars'), 1, 'How long is the turnaround between trips?', '["30 minutes","2 hours","1 day","None"]'::jsonb, 1, 'The turnaround is 2 hours.');
insert into academy_questions (section_id, sort, prompt, options, answer, explain) values ((select id from academy_sections where slug = 'fleet-cars'), 2, 'What does "car ready" mean?', '["Parked","Fuel full or charge 80%, clean, extras in","Keys found","Just washed"]'::jsonb, 1, 'Full fuel or 80% charge, clean, extras in.');
insert into academy_questions (section_id, sort, prompt, options, answer, explain) values ((select id from academy_sections where slug = 'fleet-cars'), 3, 'Can fleet waive a damage charge?', '["Yes","No: damage is an Admin''s decision","Only small damage","With the owner''s OK"]'::jsonb, 1, 'Fleet waives return charges with a reason, never damage.');
insert into academy_questions (section_id, sort, prompt, options, answer, explain) values ((select id from academy_sections where slug = 'fleet-cars'), 4, 'When does a listing photo go public?', '["At once","Once the plate is covered or marked not visible","After a week","Never"]'::jsonb, 1, 'Photos stay private until the plate is covered.');
insert into academy_questions (section_id, sort, prompt, options, answer, explain) values ((select id from academy_sections where slug = 'fleet-cars'), 5, 'What do you compare in a photo review?', '["Prices","Return photos against pickup photos","Owner documents","Insurance slips"]'::jsonb, 1, 'Compare the return photos with the pickup photos.');
insert into academy_sections (slug, title, blurb) values ('fleet-field-jobs', 'Fleet: field jobs, hours and trackers', 'Scheduling handovers and returns, field hours and corrections, trackers that stop reporting.');
insert into academy_lessons (section_id, sort, title, scenes) values ((select id from academy_sections where slug = 'fleet-field-jobs'), 1, 'Field jobs', '[{"caption":"Jobs from bookings","say":"Each confirmed booking makes its handover and return jobs. When the booking moves, its jobs move too, unless you changed them.","visual":{"kind":"title","heading":"Jobs follow the booking","text":"Unless you changed them"}},{"caption":"Assign and move","say":"Change a job with Assign, Reassign, Move or Cancel. Handovers without a job are listed first: press Schedule.","visual":{"kind":"list","heading":"A job","items":["Assign or Reassign","Move: time and place","Cancel","Schedule a missing one"]}},{"caption":"Trackers","say":"A car whose tracker is not reporting may go only with a reason, and an Admin gets an urgent task at once.","visual":{"kind":"rule","heading":"No tracker signal","text":"A reason, and an Admin is told at once.","tone":"warn"}}]'::jsonb);
insert into academy_lessons (section_id, sort, title, scenes) values ((select id from academy_sections where slug = 'fleet-field-jobs'), 2, 'Field hours', '[{"caption":"Corrections","say":"Someone forgot to clock out? Clock out for them with the time and the reason. Add, change or remove a shift, each with a reason; the change is kept in a log.","visual":{"kind":"steps","heading":"Fix hours","items":["Clock out for them","Add hours","Change or Remove","Always a reason"]}},{"caption":"Locked periods","say":"Once an Admin approves the pay run of a period, its shifts are locked. You see hours only, not rates or pay.","visual":{"kind":"title","heading":"Approved periods are locked","text":"Ask an Admin"}}]'::jsonb);
insert into academy_questions (section_id, sort, prompt, options, answer, explain) values ((select id from academy_sections where slug = 'fleet-field-jobs'), 1, 'A booking moves to a new date. What happens to its jobs?', '["Nothing","They move too, unless you changed them","They are cancelled","They are duplicated"]'::jsonb, 1, 'Jobs made from a booking follow it unless changed by hand.');
insert into academy_questions (section_id, sort, prompt, options, answer, explain) values ((select id from academy_sections where slug = 'fleet-field-jobs'), 2, 'A car must go but its tracker is not reporting. What then?', '["Never release","Release with a reason; an Admin is told at once","Release silently","Remove the tracker"]'::jsonb, 1, 'With a reason, and an Admin gets an urgent task.');
insert into academy_questions (section_id, sort, prompt, options, answer, explain) values ((select id from academy_sections where slug = 'fleet-field-jobs'), 3, 'Can you change shifts in an approved pay period?', '["Yes","No: they are locked; ask an Admin","Only add","Only remove"]'::jsonb, 1, 'Approved periods are locked.');
insert into academy_questions (section_id, sort, prompt, options, answer, explain) values ((select id from academy_sections where slug = 'fleet-field-jobs'), 4, 'What does every hours correction need?', '["Nothing","A reason","The owner''s OK","A photo"]'::jsonb, 1, 'Each change needs a reason and is logged.');
insert into academy_questions (section_id, sort, prompt, options, answer, explain) values ((select id from academy_sections where slug = 'fleet-field-jobs'), 5, 'Do fleet staff see field pay rates?', '["Yes","No: hours only","Only totals","Only overtime"]'::jsonb, 1, 'Fleet sees hours, not rates or pay.');
insert into academy_sections (slug, title, blurb) values ('admin-team', 'Admin: the team, limits and the academy', 'Staff functions and work modes, limits, commission settings, the academy: unlocking early, the gate and editing lessons.');
insert into academy_lessons (section_id, sort, title, scenes) values ((select id from academy_sections where slug = 'admin-team'), 1, 'People and functions', '[{"caption":"Functions","say":"A staff member holds any set of functions: customer service, fleet, finance, sales and field work. Each adds its menu group and its academy path.","visual":{"kind":"list","heading":"Functions","items":["Customer service","Fleet","Finance","Sales: in person or remote","Field work"]}},{"caption":"Limits","say":"Each person has a single limit: the largest refund or charge they make alone. Above it, you approve.","visual":{"kind":"rule","heading":"Limits","text":"Above a person''s limit, an Admin approves.","tone":"ok"}},{"caption":"Commission settings","say":"Program settings hold the Sales tiers in person and remote, the activity minimum, peak hours and the rate of the other functions.","visual":{"kind":"title","heading":"Program settings","text":"Every rate in one place"}}]'::jsonb);
insert into academy_lessons (section_id, sort, title, scenes) values ((select id from academy_sections where slug = 'admin-team'), 2, 'The academy', '[{"caption":"Progress","say":"Admin > Academy shows each staff member''s progress: sections passed of their paths, attempts and scores.","visual":{"kind":"title","heading":"Progress per person","text":"Sections passed, attempts, scores"}},{"caption":"Open a section early","say":"You can open a section early for one person, with a reason, for example someone experienced moving to a new function.","visual":{"kind":"steps","heading":"Open early","items":["Open the person","Choose the section","Give the reason"]}},{"caption":"The gate","say":"The academy gate is off by default: the academy records progress only. On, a staff member opens only the academy, the guide and their profile until they pass their paths.","visual":{"kind":"rule","heading":"Academy gate","text":"Off by default. On: the portal waits for the paths.","tone":"warn"}},{"caption":"Editing","say":"You edit sections, lessons, scenes and questions in the editor. Each scene has a caption, the words the voice says, and its picture. Keep it short and true to the policy.","visual":{"kind":"list","heading":"A scene","items":["Caption","Narration","Picture: title, chat, list, steps, money or rule"]}}]'::jsonb);
insert into academy_questions (section_id, sort, prompt, options, answer, explain) values ((select id from academy_sections where slug = 'admin-team'), 1, 'Is the academy gate on by default?', '["Yes","No: off, progress only","Only for Sales","Only for field"]'::jsonb, 1, 'Off by default: the academy records progress only.');
insert into academy_questions (section_id, sort, prompt, options, answer, explain) values ((select id from academy_sections where slug = 'admin-team'), 2, 'A person''s refund is above their single limit. What happens?', '["Refused","An Admin approves","Finance approves","It goes through"]'::jsonb, 1, 'Above their limit, an Admin approves.');
insert into academy_questions (section_id, sort, prompt, options, answer, explain) values ((select id from academy_sections where slug = 'admin-team'), 3, 'What does opening a section early need?', '["Nothing","A reason","The person''s signature","A quiz pass"]'::jsonb, 1, 'Every early opening is recorded with a reason.');
insert into academy_questions (section_id, sort, prompt, options, answer, explain) values ((select id from academy_sections where slug = 'admin-team'), 4, 'What does each scene of a lesson have?', '["A video file","A caption, the narration and a picture","Only text","A PDF"]'::jsonb, 1, 'Scenes are made in the browser: caption, narration and a picture.');
insert into academy_questions (section_id, sort, prompt, options, answer, explain) values ((select id from academy_sections where slug = 'admin-team'), 5, 'Where are commission rates changed?', '["In code","Program settings","The owner portal","Nowhere"]'::jsonb, 1, 'Program settings hold every rate.');
insert into academy_sections (slug, title, blurb) values ('admin-decisions', 'Admin: money decisions and owners', 'Damage and deposits, waivers, prices far under the rate sheet, owner terms and notices, flat monthly payments.');
insert into academy_lessons (section_id, sort, title, scenes) values ((select id from academy_sections where slug = 'admin-decisions'), 1, 'Damage and deposits', '[{"caption":"Keep or bill","say":"Keep the whole deposit for damage, or bill a damage charge up to the 2,500 dollar deductible: the deposit pays first, then the card on file. More goes through a claim.","visual":{"kind":"steps","heading":"Damage","items":["Compare the photos","Keep the deposit or bill up to $2,500","Over that: a claim"]}},{"caption":"Waivers","say":"Deposit waivers and prices far under the rate sheet come to you, each with the staff member''s reason. Approve or correct.","visual":{"kind":"title","heading":"Flags for an Admin","text":"Waivers and low prices, with reasons"}}]'::jsonb);
insert into academy_lessons (section_id, sort, title, scenes) values ((select id from academy_sections where slug = 'admin-decisions'), 2, 'Owner terms', '[{"caption":"Lower and higher","say":"A lower fee or share applies from the notice date. A higher fee needs 30 days'' written notice; a higher Revenue Share applies only once the owner signs an updated Vehicle Schedule.","visual":{"kind":"money","heading":"Changing terms","rows":[["Lower","From the notice date"],["Higher fee","30 days'' notice"],["Higher share","Owner signs"]]}},{"caption":"Above the signed terms","say":"Setting a booking''s Revenue Share above the car''s signed terms is Admin only, with the reason. The owner sees it.","visual":{"kind":"rule","heading":"Above terms","text":"Admin only, with a reason the owner sees.","tone":"warn"}},{"caption":"Flat monthly","say":"A flat monthly payment is set car by car. An owner with every car on it signs the Flat-Rate Enrollment Agreement.","visual":{"kind":"title","heading":"Flat monthly","text":"The Flat-Rate Enrollment Agreement"}}]'::jsonb);
insert into academy_questions (section_id, sort, prompt, options, answer, explain) values ((select id from academy_sections where slug = 'admin-decisions'), 1, 'Damage is estimated at $4,000. What can be billed to the renter directly?', '["$4,000","Up to the $2,500 deductible; the rest through a claim","Nothing","$500"]'::jsonb, 1, 'Bill up to the deductible; more goes through a claim.');
insert into academy_questions (section_id, sort, prompt, options, answer, explain) values ((select id from academy_sections where slug = 'admin-decisions'), 2, 'What pays a damage charge first?', '["The card on file","The deposit","The owner","CarmaCars"]'::jsonb, 1, 'The deposit pays first, then the card on file.');
insert into academy_questions (section_id, sort, prompt, options, answer, explain) values ((select id from academy_sections where slug = 'admin-decisions'), 3, 'You raise an owner''s fee. What is needed?', '["Nothing","30 days'' written notice","A phone call","A new car"]'::jsonb, 1, 'A higher fee comes with 30 days'' written notice.');
insert into academy_questions (section_id, sort, prompt, options, answer, explain) values ((select id from academy_sections where slug = 'admin-decisions'), 4, 'You set a booking''s Revenue Share above the signed terms. What is required?', '["Nothing","Admin only, with the reason","The renter''s OK","Finance''s OK"]'::jsonb, 1, 'Only an Admin, with the reason the owner sees.');
insert into academy_questions (section_id, sort, prompt, options, answer, explain) values ((select id from academy_sections where slug = 'admin-decisions'), 5, 'Which agreement does an owner with every car on a flat monthly payment sign?', '["None","The Flat-Rate Enrollment Agreement","A lease","The standard one"]'::jsonb, 1, 'They sign the Flat-Rate Vehicle Enrollment Agreement.');
